{
  "name": "@sandlada/opencode-ask",
  "version": "0.0.2-20261102.a",
  "description": "Read-only Ask agent for OpenCode v2. Answers questions without editing files; read-only inspection commands and pnpm test run free, anything mutating prompts.",
  "type": "module",
  "publishConfig": {
    "access": "public"
  },
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "tsc",
    "typecheck": "tsc --noEmit"
  },
  "peerDependencies": {
    "@opencode/plugin": "^2"
  },
  "devDependencies": {
    "@opencode/plugin": "2.1.4",
    "@types/node": "^26.6.5",
    "typescript": "^5.9.2"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "ask",
    "agent"
  ],
  "license": "MIT",
  "author": "Kai Orion & Sandlada",
  "packageManager": "pnpm@12.14.0"
}
